.jny{
    --pg-bg: #EDE7D9; --pg-bg2: #E6DECC; --pg-ink: #2B2722; --pg-mut: #7C7263;
    --pg-hair: rgba(43,39,34,0.16); --pg-card: rgba(251,247,236,0.75);
    --pg-acc: #8B7355; --pg-acc-deep: #6B5339; --pg-up: #4A7A52; --pg-down: #A85C48;
    --pg-shadow: 0 30px 60px rgba(40,30,20,0.18), 0 8px 18px rgba(40,30,20,0.10);
  }
@media (prefers-color-scheme: dark){
.jny{ --pg-bg: #211D17; --pg-bg2: #1A1712; --pg-ink: #E9E1CD; --pg-mut: #A69B85;
      --pg-hair: rgba(233,225,205,0.17); --pg-card: rgba(45,40,32,0.62);
      --pg-acc: #B29471; --pg-acc-deep: #C9AC86; --pg-up: #7FAE87; --pg-down: #C98B77;
      --pg-shadow: 0 30px 60px rgba(0,0,0,0.5), 0 8px 18px rgba(0,0,0,0.35); }
}
.jny[data-theme="light"]{ --pg-bg: #EDE7D9; --pg-bg2: #E6DECC; --pg-ink: #2B2722; --pg-mut: #7C7263;
    --pg-hair: rgba(43,39,34,0.16); --pg-card: rgba(251,247,236,0.75);
    --pg-acc: #8B7355; --pg-acc-deep: #6B5339; --pg-up: #4A7A52; --pg-down: #A85C48;
    --pg-shadow: 0 30px 60px rgba(40,30,20,0.18), 0 8px 18px rgba(40,30,20,0.10); }
.jny[data-theme="dark"]{ --pg-bg: #211D17; --pg-bg2: #1A1712; --pg-ink: #E9E1CD; --pg-mut: #A69B85;
    --pg-hair: rgba(233,225,205,0.17); --pg-card: rgba(45,40,32,0.62);
    --pg-acc: #B29471; --pg-acc-deep: #C9AC86; --pg-up: #7FAE87; --pg-down: #C98B77;
    --pg-shadow: 0 30px 60px rgba(0,0,0,0.5), 0 8px 18px rgba(0,0,0,0.35); }
.jny html{ -webkit-text-size-adjust: 100%; }
.jny body{ margin: 0; background: radial-gradient(120% 90% at 50% -10%, var(--pg-bg) 0%, var(--pg-bg2) 100%) fixed;
    color: var(--pg-ink); font-family: 'EB Garamond', Georgia, 'Times New Roman', serif; line-height: 1.5; }
.jny *{ box-sizing: border-box; }
.jny button{ font: inherit; }
.jny .sr-only{ position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.jny .sheet{ max-width: 1260px; margin: 0 auto; padding: 40px 28px 64px; }
.jny .head{ border-bottom: 1px solid var(--pg-hair); padding-bottom: 22px; margin-bottom: 12px; display: grid; grid-template-columns: 1fr auto; gap: 24px; align-items: start; }
.jny .head .emblem{ width: 112px; height: 124px; object-fit: cover; border-radius: 12px; border: 1px solid var(--pg-hair); margin-top: 6px; }
@media (max-width: 640px){
.jny .head{ grid-template-columns: 1fr; }
.jny .head .emblem{ display: none; }
}
.jny .head .eyeline{ display: flex; justify-content: space-between; align-items: baseline; gap: 12px; flex-wrap: wrap; }
.jny .head .eb{ font-size: 11px; font-weight: 600; letter-spacing: 3px; text-transform: uppercase; color: var(--pg-acc); }
.jny .head .stamp{ font-family: Consolas, monospace; font-size: 10px; letter-spacing: 1.5px; color: var(--pg-mut); }
.jny .head h1{ font-family: 'Cormorant Garamond', Georgia, serif; font-weight: 500; font-size: clamp(30px, 4.6vw, 44px); line-height: 1.06; margin: 10px 0 8px; text-wrap: balance; }
.jny .head .sub{ max-width: 72ch; color: var(--pg-mut); font-size: 15px; margin: 0; }
.jny .head .sub b{ color: var(--pg-ink); font-weight: 600; }
.jny .chart-chip{ display: inline-flex; align-items: center; gap: 8px; margin-top: 14px; border: 1px solid var(--pg-hair);
    border-radius: 999px; padding: 5px 14px; font-family: Consolas, monospace; font-size: 11px; letter-spacing: 0.6px; color: var(--pg-mut); }
.jny .chart-chip .zh{ font-family: 'Noto Serif TC', serif; font-size: 13px; color: var(--pg-ink); }
.jny .variant{ display: grid; grid-template-columns: 390px minmax(300px, 1fr); gap: 40px; align-items: start; padding: 40px 0; border-top: 1px solid var(--pg-hair); }
.jny .variant:first-of-type{ border-top: none; }
@media (max-width: 880px){
.jny .variant{ grid-template-columns: minmax(0, 390px); justify-content: center; }
}
.jny .vhead .vk{ display: inline-flex; align-items: center; gap: 10px; font-size: 10px; font-weight: 700; letter-spacing: 2.6px; text-transform: uppercase; color: var(--pg-acc); }
.jny .vhead .vk i{ font-style: normal; display: inline-flex; width: 22px; height: 22px; border-radius: 50%; border: 1px solid var(--pg-acc); align-items: center; justify-content: center; font-size: 11px; }
.jny .vhead h2{ font-family: 'Cormorant Garamond', Georgia, serif; font-size: 30px; font-weight: 500; margin: 8px 0 6px; }
.jny .vhead .thesis{ font-size: 15px; color: var(--pg-ink); max-width: 58ch; margin: 0 0 14px; }
.jny .vhead .thesis b{ font-weight: 600; }
.jny .vnotes{ margin: 0; padding: 0; list-style: none; max-width: 60ch; }
.jny .vnotes li{ font-size: 13.5px; color: var(--pg-mut); line-height: 1.55; padding: 9px 0; border-top: 1px dotted var(--pg-hair); }
.jny .vnotes li b{ color: var(--pg-ink); font-weight: 600; }
.jny .fourbox{ margin-top: 14px; border: 1px solid var(--pg-hair); border-left: 3px solid var(--pg-acc); border-radius: 0 12px 12px 0; padding: 12px 16px; max-width: 60ch; background: var(--pg-card); }
.jny .fourbox h5{ font-size: 10px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; margin: 0 0 5px; color: var(--pg-acc); }
.jny .fourbox p{ font-size: 13px; color: var(--pg-mut); margin: 0; line-height: 1.5; }
.jny .scrollcue{ display: inline-flex; align-items: center; gap: 7px; margin-top: 12px; font-size: 11px; letter-spacing: 1.6px; text-transform: uppercase; color: var(--pg-mut); }
.jny .scrollcue::before{ content: ''; width: 26px; border-top: 1px solid var(--pg-acc); }
.jny .reco{ margin-top: 40px; border: 1px solid var(--pg-hair); border-left: 3px solid var(--pg-acc); border-radius: 0 12px 12px 0;
    padding: 16px 20px; max-width: 94ch; background: var(--pg-card); }
.jny .reco h4{ font-size: 10px; font-weight: 700; letter-spacing: 2.4px; text-transform: uppercase; margin: 0 0 8px; color: var(--pg-acc); }
.jny .reco p{ font-size: 14px; color: var(--pg-mut); margin: 0; line-height: 1.6; }
.jny .reco p b{ color: var(--pg-ink); font-weight: 600; }
.jny .colophon{ margin-top: 34px; font-family: Consolas, monospace; font-size: 10px; letter-spacing: 1px; color: var(--pg-mut); display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.jny{
    --cream:#F8F6F0; --silk:#F1E9D6; --silkDeep:#ECE2C9; --paperHair:#CDBE9E;
    --ink:#2B2722; --inkSoft:#4A433B; --inkLight:#857D72; --inkMist:#B8AFA1;
    --bronze:#8b7355; --bronzeDark:#6B5339; --walnut:#5a4430; --dmBorder:#584A3E; --sealRed:#A04030;
    --metal:#8BA3B8; --metalDeep:#6A849A; --wood:#7A9E6E; --woodDeep:#587A4D;
    --fire:#C4745A; --fireDeep:#9E5540; --earth:#B89A6A; --earthDeep:#927750;
    --water:#5A7FA8; --waterDeep:#3E5F85; --ghost:#B8B0A2;
    --up:#4a7a52; --down:#a85c48;
    --borderStd:#D5CDBD; --borderLight:#E5DFD1;
    --cardstock:rgba(248,241,225,0.92); --quiet-bg:#EBE5D6; --quiet-border:#DCD3C0;
    --shadow-card:0 1px 0 rgba(43,39,34,0.04);
    --shadow-cta:0 6px 18px rgba(40,30,20,0.18);
    --shadow-tile:0 1px 0 rgba(43,39,34,0.04), 0 8px 18px rgba(60,46,28,0.07);
    --ease-out:cubic-bezier(0.22,1,0.36,1);
    width: 390px; height: 844px; border-radius: 47px; position: relative; overflow: hidden;
    background: #FBF7EC; color: var(--ink); font-family: 'EB Garamond', Georgia, serif;
    box-shadow: var(--pg-shadow), inset 0 0 0 8px #2B2722, inset 0 0 0 9px rgba(80,72,60,0.4);
    flex-shrink: 0; margin: 0 auto;
  }
.jny .notch{ position: absolute; top: 16px; left: 50%; transform: translateX(-50%); width: 110px; height: 26px; border-radius: 999px; background: #2B2722; z-index: 80; }
.jny .scr2{ position: absolute; inset: 8px; border-radius: 40px; overflow: hidden; display: flex; flex-direction: column; background: var(--silk); }
.jny .status2{ height: 48px; flex-shrink: 0; display: flex; align-items: flex-end; justify-content: space-between; padding: 0 30px 4px;
    font-size: 13px; font-weight: 600; color: var(--ink); position: relative; z-index: 95; }
.jny .status2 .dots{ font-size: 11px; letter-spacing: 1px; color: var(--inkSoft); }
.jny .jstage{ flex: 1; min-height: 0; position: relative; }
.jny .jscreen{ position: absolute; inset: 0; display: flex; flex-direction: column; opacity: 0; pointer-events: none;
    transform: translateX(16px); transition: opacity 240ms var(--ease-out), transform 240ms var(--ease-out); }
.jny .jscreen.active{ opacity: 1; pointer-events: auto; transform: none; }
@media (prefers-reduced-motion: reduce){
.jny .jscreen{ transition: none; transform: none; }
}
.jny .plateimg{ position: absolute; inset: -56px 0 0 0; background-size: cover; background-position: center; z-index: 0; pointer-events: none; }
.jny .eltint{ position: absolute; inset: 0; z-index: 0; pointer-events: none;
    background: radial-gradient(150% 80% at 50% -8%, rgba(139,163,184,0.10), transparent 55%); }
.jny .jscreen > *:not(.plateimg):not(.eltint):not(.ground-img2):not(.pagetint2){ position: relative; z-index: 1; }
.jny .idpill .psl.a-seal,.jny .stone .med.sealmed.a-seal,.jny .ddc .dd-ic.sealmed.a-seal,.jny .idstrip .ssl.a-seal{ background-size: 200%; background-position: 50% 42%; }
.jny .a-plate-rice{ background-image: url('data:image/jpeg;base64,'); }
.jny .a-plate-quartet{ background-image: url('data:image/jpeg;base64,'); }
.jny .a-seal{ background: url('data:image/png;base64,') center / contain no-repeat; }
.jny .a-blade{ background-image: url('data:image/jpeg;base64,'); }
.jny .a-fire{ background-image: url('data:image/jpeg;base64,'); }
.jny .a-firesq{ background-image: url('data:image/jpeg;base64,'); }
.jny .a-water{ background-image: url('data:image/jpeg;base64,'); }
.jny .a-wood{ background-image: url('data:image/jpeg;base64,'); }
.jny .a-earth{ background-image: url('data:image/jpeg;base64,'); }
.jny .a-metal{ background-image: url('data:image/jpeg;base64,'); }
.jny .pghead{ padding: 8px 22px 6px; flex-shrink: 0; }
.jny .pghead .pg-eyebrow{ font-family: 'EB Garamond', Georgia, serif; font-size: 10px; font-weight: 500; letter-spacing: 2.5px; text-transform: uppercase; color: var(--inkLight); display: block; }
.jny .backrow{ display: flex; align-items: center; gap: 6px; padding: 6px 18px 8px; flex-shrink: 0; background: none; border: none; cursor: pointer; text-align: left; }
.jny .backrow:focus-visible{ outline: 2px solid var(--bronzeDark); outline-offset: 1px; }
.jny .backrow .bico{ width: 16px; height: 16px; color: var(--inkSoft); }
.jny .backrow .bico svg{ width: 100%; height: 100%; }
.jny .backrow .bl{ font-weight: 500; font-size: 10px; letter-spacing: 2.5px; text-transform: uppercase; color: var(--inkLight); }
.jny .scrollwrap{ flex: 1; min-height: 0; overflow-y: auto; -webkit-overflow-scrolling: touch; scrollbar-width: none; }
.jny .scrollwrap::-webkit-scrollbar{ display: none; }
.jny .padv2{ display: flex; flex-direction: column; padding: 12px 18px 96px; gap: 12px; }
.jny .padv2 > *{ flex-shrink: 0; }
.jny .sec-eyebrow{ font-family: 'JetBrains Mono', Consolas, monospace; font-size: 9px; letter-spacing: 2px; text-transform: uppercase; color: var(--bronzeDark); padding: 0 2px; display: block; }
.jny .eyebrow2{ font-weight: 500; font-size: 10px; letter-spacing: 2.5px; text-transform: uppercase; color: var(--inkLight); display: block; }
.jny .body2{ font-size: 13.5px; line-height: 1.55; color: var(--inkSoft); }
.jny .cardstock{ background: var(--cardstock); border: 1px solid var(--paperHair); border-radius: 16px; padding: 14px 15px; box-shadow: var(--shadow-card); position: relative; }
.jny .idpill{ display: inline-flex; align-items: center; gap: 8px; border: 1px solid var(--paperHair); background: var(--cardstock);
    border-radius: 999px; padding: 4px 12px 4px 5px; cursor: pointer; box-shadow: var(--shadow-card); }
.jny .idpill:hover{ border-color: var(--bronze); }
.jny .idpill:focus-visible{ outline: 2px solid var(--bronzeDark); outline-offset: 2px; }
.jny .idpill .psl{ width: 24px; height: 24px; border-radius: 999px; background-color: rgba(248,244,236,0.7); box-shadow: inset 0 0 0 1px rgba(205,190,158,0.5); }
.jny .idpill .pname{ font-family: 'Cormorant Garamond', Georgia, serif; font-size: 14.5px; font-weight: 600; color: var(--walnut); }
.jny .idpill .pshare{ width: 13px; height: 13px; color: var(--bronzeDark); }
.jny .stones{ display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }
.jny .stone{ position: relative; background: var(--cardstock); border: 1px solid var(--paperHair); border-radius: 16px;
    box-shadow: var(--shadow-tile); padding: 10px 12px 11px; text-align: left; cursor: pointer;
    display: flex; flex-direction: column; gap: 4px; transition: transform 160ms var(--ease-out); }
.jny .stone:hover{ transform: translateY(-2px); }
.jny .stone:focus-visible{ outline: 2px solid var(--bronzeDark); outline-offset: 2px; }
.jny .stone .sk{ font-family: Cinzel, Georgia, serif; font-size: 8px; font-weight: 600; letter-spacing: 2.2px; color: var(--bronzeDark); text-transform: uppercase; }
.jny .stone .srow{ display: flex; align-items: center; gap: 8px; }
.jny .stone .med{ width: 32px; height: 32px; border-radius: 10px; flex: none; display: flex; align-items: center; justify-content: center;
    background-color: color-mix(in srgb, var(--pig, var(--paperHair)) 11%, transparent); border: 1px solid color-mix(in srgb, var(--pig, var(--paperHair)) 30%, transparent); }
.jny .stone .med svg{ width: 18px; height: 18px; fill: var(--pigDeep, var(--ink)); }
.jny .stone .med.sealmed{ background-color: rgba(248,244,236,0.7); border-radius: 999px; box-shadow: inset 0 0 0 1px rgba(205,190,158,0.5); }
.jny .stone .word{ font-family: 'Cormorant Garamond', Georgia, serif; font-size: 19px; font-weight: 600; line-height: 1; color: var(--pigDeep, var(--walnut)); }
.jny .stone .word .zh{ font-family: 'Noto Serif TC', serif; font-size: 12px; font-weight: 400; color: var(--inkLight); margin-left: 3px; }
.jny .stone .sline{ font-size: 10.5px; font-style: italic; line-height: 1.35; color: var(--inkLight); }
.jny .stone .spip{ position: absolute; top: 9px; right: 9px; width: 16px; height: 16px; border-radius: 50%; border: 1.3px solid;
    background: rgba(248,244,236,0.95); display: flex; align-items: center; justify-content: center; }
.jny .stone .spip svg{ width: 9px; height: 9px; }
.jny .stone .spip.up{ border-color: var(--up); color: var(--up); }
.jny .stone .spip.down{ border-color: var(--down); color: var(--down); }
.jny .stone .spip.who{ border-color: var(--dmBorder); color: var(--ink); }
.jny .ddc{ display: grid; grid-template-columns: 38px 1fr 26px; gap: 12px; align-items: center; width: 100%; text-align: left;
    background: var(--cardstock); border: 1px solid var(--borderStd); border-radius: 13px; box-shadow: var(--shadow-card);
    padding: 10px 13px; cursor: pointer; transition: transform 150ms var(--ease-out); }
.jny .ddc + .ddc{ margin-top: 7px; }
.jny .ddc:hover{ transform: translateY(-1px); }
.jny .ddc:focus-visible{ outline: 2px solid var(--bronzeDark); outline-offset: 2px; }
.jny .ddc .dd-ic{ width: 38px; height: 38px; border-radius: 10px; display: flex; align-items: center; justify-content: center;
    background-color: color-mix(in srgb, var(--pig, var(--paperHair)) 10%, transparent); border: 1px solid color-mix(in srgb, var(--pig, var(--paperHair)) 26%, transparent); }
.jny .ddc .dd-ic svg{ width: 20px; height: 20px; fill: var(--pigDeep, var(--ink)); }
.jny .ddc .dd-ic.sealmed{ background-color: rgba(248,244,236,0.7); border-radius: 999px; box-shadow: inset 0 0 0 1px rgba(205,190,158,0.5); }
.jny .ddc .dd-k{ font-family: Cinzel, Georgia, serif; font-size: 8px; font-weight: 600; letter-spacing: 2.2px; color: var(--bronzeDark); text-transform: uppercase; display: block; }
.jny .ddc .dd-v{ font-family: 'Cormorant Garamond', Georgia, serif; font-size: 16.5px; font-weight: 600; line-height: 1.15; color: var(--ink); display: block; margin-top: 1px; }
.jny .ddc .dd-v .en{ color: var(--pigDeep, var(--walnut)); }
.jny .ddc .dd-v .zh{ font-family: 'Noto Serif TC', serif; font-size: 11.5px; font-weight: 400; color: var(--inkLight); }
.jny .ddc .dd-v .tail{ font-family: 'EB Garamond', Georgia, serif; font-size: 11.5px; font-weight: 400; color: var(--inkSoft); }
.jny .ddc .dd-go{ width: 26px; height: 26px; border-radius: 999px; display: flex; align-items: center; justify-content: center;
    background: color-mix(in srgb, var(--pig, var(--paperHair)) 12%, transparent); color: var(--pigDeep, var(--bronzeDark)); }
.jny .ddc .dd-go svg{ width: 13px; height: 13px; }
.jny .poster{ padding: 4px 2px; border-top: 1.5px solid var(--paperHair); border-bottom: 1.5px solid var(--paperHair);
    background: linear-gradient(90deg, rgba(253,250,242,0) 0%, rgba(253,250,242,0.8) 10%, rgba(253,250,242,0.8) 90%, rgba(253,250,242,0) 100%); }
.jny .pos-row{ display: grid; grid-template-columns: 82px 1fr 18px; gap: 10px; align-items: baseline; width: 100%; text-align: left;
    background: none; border: none; cursor: pointer; padding: 10px 4px; }
.jny .pos-row + .pos-row{ border-top: 1px dotted rgba(139,115,85,0.3); }
.jny .pos-row:hover .pw{ text-shadow: 0 0 1px currentColor; }
.jny .pos-row:focus-visible{ outline: 2px solid var(--bronzeDark); outline-offset: 1px; }
.jny .pos-row .pk{ font-family: Cinzel, Georgia, serif; font-size: 9px; font-weight: 600; letter-spacing: 2.4px; color: var(--bronzeDark); text-transform: uppercase; }
.jny .pos-row .pw{ font-family: 'Cormorant Garamond', Georgia, serif; font-size: 23px; font-weight: 600; line-height: 1.05; color: var(--pigDeep, var(--walnut)); }
.jny .pos-row .pw .zh{ font-family: 'Noto Serif TC', serif; font-size: 14px; font-weight: 400; color: var(--inkLight); }
.jny .pos-row .pw .tail{ display: block; font-family: 'EB Garamond', Georgia, serif; font-size: 11px; font-weight: 400; color: var(--inkSoft); margin-top: 1px; letter-spacing: 0.2px; }
.jny .pos-row .ppip{ width: 17px; height: 17px; border-radius: 50%; border: 1.3px solid; background: rgba(248,244,236,0.9);
    display: inline-flex; align-items: center; justify-content: center; align-self: center; }
.jny .pos-row .ppip svg{ width: 9.5px; height: 9.5px; }
.jny .pos-row .ppip.up{ border-color: var(--up); color: var(--up); }
.jny .pos-row .ppip.down{ border-color: var(--down); color: var(--down); }
.jny .pos-row .ppip.who{ border-color: var(--dmBorder); color: var(--ink); }
.jny .idbanner{ position: relative; overflow: hidden; display: flex; align-items: center; min-height: 92px; padding: 13px 15px;
    border-radius: 16px; background: var(--cardstock); border: 1px solid var(--borderStd); box-shadow: 0 4px 12px rgba(60,46,28,0.06);
    width: 100%; text-align: left; cursor: pointer; transition: transform 160ms var(--ease-out); }
.jny .idbanner:hover{ transform: translateY(-1px); }
.jny .idbanner:focus-visible{ outline: 2px solid var(--bronzeDark); outline-offset: 2px; }
.jny .idbanner .bart{ position: absolute; right: 0; top: 0; bottom: 0; width: 55%; background-size: cover; background-position: center 30%; }
.jny .idbanner .bfade{ position: absolute; right: 0; top: 0; bottom: 0; width: 55%;
    background: linear-gradient(to right, rgba(248,241,225,0.96) 6%, rgba(244,236,217,0.4) 45%, transparent 85%); }
.jny .idbanner .btx{ position: relative; z-index: 2; max-width: 62%; }
.jny .idbanner .bey{ font-family: 'JetBrains Mono', Consolas, monospace; font-size: 8px; letter-spacing: 1.8px; text-transform: uppercase; color: var(--metalDeep); display: block; }
.jny .idbanner .bnm{ font-family: 'Cormorant Garamond', Georgia, serif; font-size: 22px; font-weight: 600; color: var(--walnut); line-height: 1.05; margin-top: 2px; }
.jny .idbanner .bman{ font-size: 11px; font-style: italic; color: var(--inkSoft); margin-top: 2px; display: block; }
.jny .idstrip{ display: flex; gap: 10px; align-items: center; background: var(--cardstock); border: 1px solid var(--paperHair);
    border-radius: 14px; box-shadow: var(--shadow-card); padding: 8px 12px; width: 100%; text-align: left; cursor: pointer; }
.jny .idstrip:focus-visible{ outline: 2px solid var(--bronzeDark); outline-offset: 2px; }
.jny .idstrip .ssl{ width: 36px; height: 36px; border-radius: 999px; flex: none; background-color: rgba(248,244,236,0.7); box-shadow: inset 0 0 0 1px rgba(205,190,158,0.5); }
