.jny .cardswitch{border:1px solid var(--pg-hair);border-radius:14px;background:var(--pg-card);padding:15px 17px;margin-bottom:22px}
.jny .cardswitch .cs-lbl{font-family:'JetBrains Mono',Consolas,monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;color:var(--pg-acc);display:block;margin-bottom:10px}
.jny .cs-seg{display:inline-flex;border:1px solid var(--pg-hair);border-radius:999px;overflow:hidden}
.jny .cs-seg button{border:0;background:none;color:var(--pg-mut);padding:8px 17px;font-family:'JetBrains Mono',Consolas,monospace;font-size:10px;letter-spacing:1.2px;text-transform:uppercase;cursor:pointer;transition:background .16s,color .16s}
.jny .cs-seg button+button{border-left:1px solid var(--pg-hair)}
.jny .cs-seg button[aria-pressed="true"]{background:var(--pg-ink);color:var(--pg-bg)}
.jny .cs-note{font-size:12px;color:var(--pg-mut);line-height:1.45;margin:11px 0 0}

/* ═══════════ app-integration overrides (round 2) ═══════════ */
.jny{position:absolute;inset:0;overflow:hidden;font-family:'EB Garamond',Georgia,serif}
.jny.jphone{width:100%!important;height:100%!important;min-height:0;border:none!important;border-radius:0!important;box-shadow:none!important;background:var(--silk,#F1E9D6);transform:none!important;margin:0!important}
.jny .scr2{inset:0;border-radius:0}
.jny .notch,.jny .tabbar2{display:none}
.jny .gseal.gimg{background-size:contain;background-repeat:no-repeat}
.jny .wordsnote{margin-top:-70px;margin-bottom:calc(22px + env(safe-area-inset-bottom,0px))}
.jny .wordpop{position:absolute;inset:0;z-index:120;display:flex;align-items:center;justify-content:center;padding:26px}
.jny .wordpop[hidden]{display:none}
/* round-2 fixes: painting-mode center seal on live wheels (non-庚 stems use
   the proc medallions — raw stem pngs are full paintings, not seal chips);
   glossary sheet above every layer */
.jny .wheel .center-seal.ms{background-position:center;background-size:contain;background-repeat:no-repeat;background-color:transparent;border:none;box-shadow:none;border-radius:50%}
.jny .wordpop{z-index:210 !important}
/* device alignment: the app tab bar grows by the safe-area inset (home
   indicator); the dock docks above the REAL bar height, matching the
   prototype's flush 76px rhythm on every device */
.jny[data-ca="dock"] .ca-dock{bottom:calc(76px + env(safe-area-inset-bottom, 0px)) !important}
/* the dock's mist — content approaching the dock melts into a silk fade
   instead of hard-clipping against its edge: the peek stays a scroll hint
   without reading as a broken crop. Rides the dock (fades out on merge). */
.jny[data-ca="dock"] .ca-dock::before{content:'';position:absolute;left:-14px;right:-14px;top:-38px;height:38px;background:linear-gradient(to bottom,rgba(242,235,220,0) 0%,rgba(242,235,220,0.72) 55%,rgba(243,236,222,0.96) 100%);pointer-events:none}
/* the veil, full-bleed (owner 2026-07-23): the mist now runs from above the
   dock all the way down to the screen bottom — one silk sheet BEHIND the dock
   band (z:-1 within its stacking context) and over the page, so no raw page
   or color seam shows at the dock's flanks or beneath it. */
.jny[data-ca="dock"] .ca-dock::before{top:-38px;bottom:calc(-1 * (76px + env(safe-area-inset-bottom, 0px)));height:auto;left:-26px;right:-26px;z-index:-1;background:linear-gradient(to bottom,rgba(242,235,220,0) 0%,rgba(242,235,220,0.82) 30%,rgba(243,236,222,0.97) 58%,rgba(243,236,222,0.98) 100%)}
/* SEEK/SKIP row format (owner 2026-07-23): "{Element} is your {Relation}"
   inline — pigment name · muted connective · ink relation — with the mono
   presence % beneath. Matches the supplied design crop. */
.jny .ik-crow{padding:10px 0}
.jny .ik-crow .cr-line{display:flex;align-items:baseline;gap:7px;flex-wrap:wrap}
.jny .cr-el{font-family:'Cormorant Garamond',Georgia,serif;font-size:17px;font-weight:600;line-height:1.1}
.jny .cr-isyour{font-family:'EB Garamond',Georgia,serif;font-size:10.5px;letter-spacing:0.6px;color:var(--inkLight)}
.jny .cr-rel{font-family:'Cormorant Garamond',Georgia,serif;font-size:17px;font-weight:600;color:var(--ink);line-height:1.1}
.jny .cr-pct{display:block;font-family:'JetBrains Mono',Consolas,monospace;font-size:10px;letter-spacing:1px;color:var(--inkSoft);margin-top:3px}
/* crop-true scale (measured against the 8.5px role-pill in the supplied
   design): single-line rows in the 390px two-column layout */
.jny .ik-crow .cr-line{gap:5px;flex-wrap:nowrap;white-space:nowrap}
.jny .cr-el{font-size:15px}
.jny .cr-rel{font-size:15px}
.jny .cr-isyour{font-size:9.5px;letter-spacing:0.4px}
